#!/usr/bin/env python3
"""Regenerate third-party/manifest.json from the live machine state.

Sources of truth on the machine:
  ~/.agents/.skill-lock.json                  installed skills + their upstream repos
  ~/.claude/plugins/known_marketplaces.json   plugin marketplaces
  ~/.claude/settings.json                     which plugins are enabled

Run after installing or removing a third-party skill/plugin, then commit the diff.
"""

import json
import pathlib
import datetime

HOME = pathlib.Path.home()
OUT = pathlib.Path(__file__).parent / "manifest.json"

# Vendored in this repo instead of listed here — see skills/ and rules/.
VENDORED = {"dotnet-master", "neon-postgres"}


def load(path, default):
    try:
        return json.loads(pathlib.Path(path).read_text())
    except (OSError, json.JSONDecodeError):
        return default


lock = load(HOME / ".agents/.skill-lock.json", {})
markets = load(HOME / ".claude/plugins/known_marketplaces.json", {})
settings = load(HOME / ".claude/settings.json", {})

skills = [
    {
        "name": name,
        "repo": meta.get("source"),
        "url": meta.get("sourceUrl"),
        # path to the SKILL.md inside the repo; its parent dir is what gets copied
        "skillPath": meta.get("skillPath"),
        "pinnedFolderHash": meta.get("skillFolderHash"),
    }
    for name, meta in sorted(lock.get("skills", {}).items())
    if name not in VENDORED
]

manifest = {
    "$comment": "Generated by refresh-manifest.py. Third-party artifacts are NOT vendored "
    "— they are reinstalled from upstream by install.sh. Edit the machine, "
    "rerun the script, commit the diff.",
    "generatedAt": datetime.date.today().isoformat(),
    "skills": skills,
    "marketplaces": {
        name: meta.get("source", {}).get("repo")
        for name, meta in sorted(markets.items())
    },
    "plugins": settings.get("enabledPlugins", {}),
    "tools": [
        {
            "name": "graphify",
            "why": "ships its own SKILL.md and self-updates; see rules/graphify.md",
            "check": "which graphify",
            "pinnedVersion": "0.7.15",
        }
    ],
}

OUT.write_text(json.dumps(manifest, indent=2) + "\n")
print(f"wrote {OUT} — {len(skills)} skills, "
      f"{len(manifest['marketplaces'])} marketplaces, "
      f"{sum(manifest['plugins'].values())} enabled plugins")
